const ExcelJS = (await import("exceljs")).default;
const path = await import("node:path");

// 內建示範資料:一段最常見的「流水帳」(實務上這段會換成從信箱附件/上傳檔讀進來的資料)
const rows = [
  { 日期: "2026-08-01", 品項: "美式咖啡豆 1kg", 分類: "飲品", 金額: 12800 },
  { 日期: "2026-08-01", 品項: "肉桂捲禮盒", 分類: "烘焙", 金額: 9600 },
  { 日期: "2026-08-02", 品項: "冷萃咖啡瓶裝", 分類: "飲品", 金額: 15400 },
  { 日期: "2026-08-03", 品項: "可頌(每日出爐)", 分類: "烘焙", 金額: 7200 },
  { 日期: "2026-08-03", 品項: "掛耳包 30 入", 分類: "飲品", 金額: 21000 },
  { 日期: "2026-08-04", 品項: "生日蛋糕預訂", 分類: "烘焙", 金額: 18800 },
  { 日期: "2026-08-05", 品項: "門市器材維護", 分類: "營運", 金額: 6500 },
  { 日期: "2026-08-06", 品項: "茶類新品試賣", 分類: "飲品", 金額: 8900 },
];

const byCat = {};
for (const r of rows) (byCat[r.分類] ??= []).push(r);

const wb = new ExcelJS.Workbook();
const ws = wb.addWorksheet("銷售報表");
const thin = { top: { style: "thin" }, left: { style: "thin" }, right: { style: "thin" }, bottom: { style: "thin" } };

ws.mergeCells("A1:D1");
const title = ws.getCell("A1");
title.value = "門市銷售週報（示範資料）";
title.font = { bold: true, size: 14, color: { argb: "FFFFFFFF" } };
title.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF002060" } };
title.alignment = { horizontal: "center", vertical: "middle" };
ws.getRow(1).height = 26;

const headerRow = ws.addRow(["日期", "品項", "分類", "金額"]);
for (let c = 1; c <= 4; c++) {
  const cell = headerRow.getCell(c);
  cell.font = { bold: true, color: { argb: "FFFFFFFF" } };
  cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF4472C4" } };
  cell.alignment = { horizontal: "center" };
  cell.border = thin;
}

let total = 0;
for (const [cat, items] of Object.entries(byCat)) {
  for (const r of items) {
    const row = ws.addRow([r.日期, r.品項, r.分類, r.金額]);
    for (let c = 1; c <= 4; c++) row.getCell(c).border = thin;
    row.getCell(4).numFmt = "#,##0";
  }
  const sub = items.reduce((s, r) => s + r.金額, 0);
  total += sub;
  const subRow = ws.addRow(["", cat + " 小計", "", sub]);
  for (let c = 1; c <= 4; c++) {
    const cell = subRow.getCell(c);
    cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFD9E1F2" } };
    cell.font = { bold: true };
    cell.border = thin;
  }
  subRow.getCell(4).numFmt = "#,##0";
}
const totalRow = ws.addRow(["", "總計", "", total]);
for (let c = 1; c <= 4; c++) {
  const cell = totalRow.getCell(c);
  cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFC000" } };
  cell.font = { bold: true };
  cell.border = thin;
}
totalRow.getCell(4).numFmt = "#,##0";
ws.getColumn(1).width = 12; ws.getColumn(2).width = 20; ws.getColumn(3).width = 10; ws.getColumn(4).width = 12;

const fileName = "銷售週報(範例).xlsx";
const file = path.join(ctx.outputDir, fileName);
await wb.xlsx.writeFile(file);
ctx.registerFile(fileName, file, "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
ctx.log(`報表完成:${rows.length} 筆、${Object.keys(byCat).length} 個分類、總計 ${total.toLocaleString()} 元`);
return { ...ctx.input, 筆數: rows.length, 總金額: total.toLocaleString(), 報表檔名: fileName };
